import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { AuthService } from '../../../../core/services/auth.service';
@Component({selector:'app-forgot-password',standalone:true,imports:[FormsModule,RouterLink],template:`<div class="w-full"><p class="eyebrow">Khôi phục tài khoản</p><h1 class="mt-3 font-serif text-4xl font-semibold tracking-tight">Quên mật khẩu</h1><p class="mt-3 text-sm leading-6 text-muted">Nhập email tài khoản. Nếu email tồn tại, hệ thống sẽ tạo mã xác minh.</p><form (submit)="submit($event)" class="mt-7 space-y-5"><label><span class="field-label">Email</span><input class="field" type="email" [(ngModel)]="email" name="email" required autocomplete="email"/></label>@if(message()){<div class="rounded-xl border border-border bg-surface p-5 text-sm leading-6">{{message()}}@if(devCode()){<p class="mt-2 font-semibold text-primary">Mã DEV: {{devCode()}}</p>}</div>}<button class="btn-primary w-full min-h-12" [disabled]="loading()">{{loading()?'Đang xử lý...':'Gửi mã xác minh'}}</button><a routerLink="/login" class="block text-center text-sm font-medium text-primary hover:text-primary-dark">Quay lại đăng nhập</a></form></div>`})
export class ForgotPasswordComponent{private auth=inject(AuthService);email='';loading=signal(false);message=signal('');devCode=signal('');submit(e:Event){e.preventDefault();this.loading.set(true);this.auth.forgotPassword(this.email).subscribe({next:r=>{this.message.set(r.message||'Đã xử lý yêu cầu.');this.devCode.set((r.data as any)?.code||'');this.loading.set(false);},error:e=>{this.message.set(e.error?.message||'Không thể xử lý yêu cầu.');this.loading.set(false);}});}}